INSERT INTO medicines (id, organization_id, brand_name, generic_name, category, manufacturer, dosage_form, strength, active_ingredients, inactive_excipients, tablet_shape, tablet_color, score_line, coating_type, indications, dosage_instructions, warnings_and_precautions, side_effects, storage_conditions, schedule_type, voice_summary_en, voice_summary_hi, voice_summary_mr, status)
VALUES (4, 1, 'Pan 40', 'Pantoprazole Gastro-resistant Tablets IP', 'Proton Pump Inhibitor (Antacid)', 'Alkem Laboratories', 'Tablet', '40 mg', '[{"name": "Pantoprazole Sodium Sesquihydrate IP eq. to Pantoprazole", "strength": "40", "unit": "mg", "purpose": "Gastric Acid Reducer"}]', '["Sodium Carbonate", "Mannitol", "Crospovidone", "Povidone", "Calcium Stearate", "Methacrylic Acid Copolymer", "Triethyl Citrate", "Yellow Iron Oxide"]', 'Round biconvex', 'Yellow', 'None', 'Enteric-coated (Gastro-resistant)', 'Acidity, heartburn, gastroesophageal reflux disease (GERD), gastric and duodenal ulcers.', 'Swallow whole with a glass of water in the morning, 30 to 60 minutes before breakfast.', 'Do not crush, break, or chew the tablet. Long term use requires monitoring of Vitamin B12 and Magnesium.', 'Headache, diarrhea, dizziness, flatulence.', 'Store below 25°C in original package. Protect from humidity.', 'Schedule H', 'Pan 40 Pantoprazole tablet for acidity and heartburn. Swallow whole 30 minutes before morning breakfast. Do not crush.', 'पैन 40 एसिडिटी और सीने में जलन की दवा। सुबह नाश्ते से 30 मिनट पहले एक गोली पूरी निगलें।', 'पॅन 40 ॲसिडिटीची गोळी. सकाळी नाश्त्याच्या 30 मिनिटे आधी न चावता एक गोळी गिळा.', 'active')
ON CONFLICT (id) DO NOTHING;
