VALUES (5, 1, 'Glycomet 500', 'Metformin Hydrochloride Prolonged-Release Tablets IP', 'Antidiabetic (Biguanide)', 'USV Private Limited', 'Tablet', '500 mg', '[{"name": "Metformin Hydrochloride IP", "strength": "500", "unit": "mg", "purpose": "Oral Hypoglycemic"}]', '["Hydroxypropyl Methylcellulose (HPMC)", "Sodium Carboxymethylcellulose", "Microcrystalline Cellulose", "Magnesium Stearate"]', 'Round flat-faced', 'White', 'None', 'Prolonged-release uncoated', 'Management of Type 2 Diabetes Mellitus to maintain healthy blood glucose levels.', 'Take with or immediately after meals (breakfast/dinner) to reduce stomach discomfort.', 'Avoid heavy alcohol consumption. Risk of lactic acidosis in kidney or liver impairment.', 'Nausea, metallic taste, stomach pain, loss of appetite, diarrhea.', 'Store below 30°C. Protect from light and moisture.', 'Schedule H', 'Glycomet 500 Metformin tablet for Type 2 Diabetes. Take with your meal to control blood sugar. Swallow whole.', 'ग्लाइकोमेट 500 शुगर (डायबिटीज) की दवा। इसे भोजन के तुरंत बाद पानी से लें।', 'ग्लायकोमेट 500 मधुमेहाची गोळी. रक्तातील साखर नियंत्रणात ठेवण्यासाठी जेवणासोबत घ्या.', 'active')
ON CONFLICT (id) DO NOTHING;
